import sqlite3
from datetime import datetime, timezone

DB_PATH = "hr.db"
ALLOWED_ROLES = {"payroll_viewer", "payroll_editor", "payroll_admin"}


def _log_grant(con, user_id, role, granted_by):
    con.execute(
        "INSERT INTO access_audit (user_id, role, granted_by, granted_at) VALUES (?, ?, ?, ?)",
        (user_id, role, granted_by, datetime.now(timezone.utc).isoformat()),
    )


def grant_payroll_role(user_id: str, role: str, granted_by: str) -> str:
    if role not in ALLOWED_ROLES:
        return f"Unknown role {role}"
    con = sqlite3.connect(DB_PATH)
    admin = con.execute(
        "SELECT 1 FROM user_roles WHERE user_id = ? AND role = 'payroll_admin'", (granted_by,)
    ).fetchone()
    if not admin:
        con.close()
        return "Granting user is not a payroll admin"
    con.execute(
        "INSERT OR IGNORE INTO user_roles (user_id, role) VALUES (?, ?)", (user_id, role)
    )
    _log_grant(con, user_id, role, granted_by)
    con.commit()
    con.close()
    return f"Granted {role} to {user_id}"
